class Solution {
public:
    int minimumCapacityBox(vector<int>& capacity, int itemSize) {
        vector<int> order(capacity.size());
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) {
            if (capacity[a] != capacity[b]) return capacity[a] < capacity[b];
            return a < b;
        });
        for (int i : order)
            if (capacity[i] >= itemSize) return i;
        return -1;
    }
};

