class Solution {
    public int minimumCapacityBox(int[] capacity, int itemSize) {
        Integer[] order = new Integer[capacity.length];
        for (int i = 0; i < order.length; i++) order[i] = i;
        java.util.Arrays.sort(order, (a, b) -> capacity[a] != capacity[b]
                ? Integer.compare(capacity[a], capacity[b]) : Integer.compare(a, b));
        for (int i : order)
            if (capacity[i] >= itemSize) return i;
        return -1;
    }
}

